const scalePt = (p) => [center[0] + k * (p[0] - center[0]), center[1] + k * (p[1] - center[1]), 0];
const bigTri = new Polygon({ vertices: [scalePt(A), scalePt(B), scalePt(C)], color: ORANGE });
bigTri.setFill(ORANGE, 0.18);

